1	import matter from 'gray-matter';
2	import { marked } from 'marked';
3	
4	export interface PageMetadata {
5	  title?: string;
6	  date?: string;
7	  tags?: string[];
8	  [key: string]: string | string[] | undefined;
9	}
10	
11	export interface ParsedPage {
12	  content: string;
13	  metadata: PageMetadata;
14	}
15	
16	function parseYamlFrontmatter(yamlStr: string): Record<string, string | string[]> {
17	  const result: Record<string, string | string[]> = {};
18	  const lines = yamlStr.trim().split('\n');
19	
20	  for (const line of lines) {
21	    const colonIndex = line.indexOf(':');
22	    if (colonIndex === -1) continue;
23	
24	    const key = line.substring(0, colonIndex).trim();
25	    const value = line.substring(colonIndex + 1).trim();
26	
27	    if (key === 'tags') {
28	      const tags = value.split(',').map(tag => tag.trim()).filter(tag => tag.length > 0);
29	      if (tags.length > 0) {
30	        result[key] = tags;
31	      }
32	    } else if (value.length > 0) {
33	      result[key] = value;
34	    }
35	  }
36	
37	  return result;
38	}
39	
40	export async function parseMarkdown(content: string): Promise<ParsedPage> {
41	  const result = matter(content);
42	
43	  let metadata: PageMetadata = {};
44	
45	  if (typeof result.data === 'object' && result.data !== null) {
46	    metadata = result.data as PageMetadata;
47	  }
48	
49	  const html = await marked.parse(result.content);
50	
51	  return {
52	    content: html,
53	    metadata
54	  };
55	}
56	
57	export async function parseMarkdownWithYaml(content: string): Promise<ParsedPage> {
58	  const fencedRegex = /^---\n([\s\S]*?)\n---\n/;
59	  const match = content.match(fencedRegex);
60	
61	  let metadata: PageMetadata = {};
62	  let markdown = content;
63	
64	  if (match) {
65	    const yamlBlock = match[1];
66	    markdown = content.substring(match[0].length);
67	
68	    const parsedYaml = parseYamlFrontmatter(yamlBlock);
69	    metadata = {
70	      title: parsedYaml.title as string | undefined,
71	      date: parsedYaml.date as string | undefined,
72	      tags: Array.isArray(parsedYaml.tags) ? parsedYaml.tags : undefined,
73	      ...Object.fromEntries(
74	        Object.entries(parsedYaml).filter(([key]) => !['title', 'date', 'tags'].includes(key))
75	      )
76	    };
77	  }
78	
79	  const html = await marked.parse(markdown);
80	
81	  return {
82	    content: html,
83	    metadata
84	  };
85	}
