1	import fs from 'fs';
2	import path from 'path';
3	import { parseMarkdownWithYaml, type PageMetadata } from './parser.js';
4	
5	export interface PageData {
6	  slug: string;
7	  filename: string;
8	  content: string;
9	  metadata: PageMetadata;
10	}
11	
12	export interface GeneratorOptions {
13	  contentDir: string;
14	  outputDir: string;
15	}
16	
17	function slugFromFilename(filename: string): string {
18	  return filename.replace(/\.md$/, '');
19	}
20	
21	function generatePageHtml(page: PageData): string {
22	  const title = page.metadata.title || page.slug;
23	  const date = page.metadata.date ? `<p class="date">${page.metadata.date}</p>` : '';
24	  const tags = page.metadata.tags && page.metadata.tags.length > 0
25	    ? `<div class="tags">${page.metadata.tags.map(tag => `<span class="tag">${tag}</span>`).join('')}</div>`
26	    : '';
27	
28	  return `<!DOCTYPE html>
29	<html lang="en">
30	<head>
31	  <meta charset="UTF-8">
32	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
33	  <title>${escapeHtml(title)}</title>
34	  <style>
35	    body { font-family: sans-serif; line-height: 1.6; max-width: 800px; margin: 0 auto; padding: 20px; }
36	    a { color: #0066cc; }
37	    .date { color: #666; font-size: 0.9em; }
38	    .tags { margin: 10px 0; }
39	    .tag { display: inline-block; background: #f0f0f0; padding: 2px 8px; margin: 2px; border-radius: 3px; font-size: 0.9em; }
40	    nav { border-bottom: 1px solid #ddd; margin-bottom: 20px; padding-bottom: 10px; }
41	  </style>
42	</head>
43	<body>
44	  <nav>
45	    <a href="index.html">← Home</a>
46	  </nav>
47	  <article>
48	    <h1>${escapeHtml(title)}</h1>
49	    ${date}
50	    ${tags}
51	    <div class="content">
52	      ${page.content}
53	    </div>
54	  </article>
55	</body>
56	</html>`;
57	}
58	
59	function generateIndexHtml(pages: PageData[]): string {
60	  const pageLinks = pages
61	    .sort((a, b) => {
62	      const dateA = new Date(a.metadata.date || '').getTime();
63	      const dateB = new Date(b.metadata.date || '').getTime();
64	      return dateB - dateA;
65	    })
66	    .map(page => {
67	      const title = page.metadata.title || page.slug;
68	      const dateStr = page.metadata.date ? ` (${page.metadata.date})` : '';
69	      return `<li><a href="${page.slug}.html">${escapeHtml(title)}</a>${dateStr}</li>`;
70	    })
71	    .join('\n    ');
72	
73	  return `<!DOCTYPE html>
74	<html lang="en">
75	<head>
76	  <meta charset="UTF-8">
77	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
78	  <title>Home</title>
79	  <style>
80	    body { font-family: sans-serif; line-height: 1.6; max-width: 800px; margin: 0 auto; padding: 20px; }
81	    a { color: #0066cc; }
82	    li { margin: 8px 0; }
83	  </style>
84	</head>
85	<body>
86	  <h1>Pages</h1>
87	  <ul>
88	    ${pageLinks}
89	  </ul>
90	</body>
91	</html>`;
92	}
93	
94	function escapeHtml(text: string): string {
95	  const map: Record<string, string> = {
96	    '&': '&amp;',
97	    '<': '&lt;',
98	    '>': '&gt;',
99	    '"': '&quot;',
100	    "'": '&#039;'
101	  };
102	  return text.replace(/[&<>"']/g, char => map[char]);
103	}
104	
105	export async function generate(options: GeneratorOptions): Promise<void> {
106	  const { contentDir, outputDir } = options;
107	
108	  if (!fs.existsSync(contentDir)) {
109	    throw new Error(`Content directory not found: ${contentDir}`);
110	  }
111	
112	  if (!fs.existsSync(outputDir)) {
113	    fs.mkdirSync(outputDir, { recursive: true });
114	  }
115	
116	  const files = fs.readdirSync(contentDir).filter(file => file.endsWith('.md'));
117	
118	  if (files.length === 0) {
119	    throw new Error(`No markdown files found in ${contentDir}`);
120	  }
121	
122	  const pages: PageData[] = [];
123	
124	  for (const file of files) {
125	    const filePath = path.join(contentDir, file);
126	    const content = fs.readFileSync(filePath, 'utf-8');
127	    const parsed = await parseMarkdownWithYaml(content);
128	
129	    const page: PageData = {
130	      slug: slugFromFilename(file),
131	      filename: file,
132	      content: parsed.content,
133	      metadata: parsed.metadata
134	    };
135	
136	    pages.push(page);
137	
138	    const pageHtml = generatePageHtml(page);
139	    const outputPath = path.join(outputDir, `${page.slug}.html`);
140	    fs.writeFileSync(outputPath, pageHtml, 'utf-8');
141	  }
142	
143	  const indexHtml = generateIndexHtml(pages);
144	  const indexPath = path.join(outputDir, 'index.html');
145	  fs.writeFileSync(indexPath, indexHtml, 'utf-8');
146	
147	  console.log(`Generated site with ${pages.length} page(s) in ${outputDir}`);
148	}
