7	export function parseArgs(argv: string[]): CliArgs {
8	  const args: CliArgs = {
9	    command: 'build',
10	    contentDir: './content',
11	    outputDir: './dist'
12	  };
13	
14	  for (let i = 0; i < argv.length; i++) {
15	    const arg = argv[i];
16	
17	    if (arg === '--content' && i + 1 < argv.length) {
18	      args.contentDir = argv[++i];
19	    } else if (arg === '--output' && i + 1 < argv.length) {
20	      args.outputDir = argv[++i];
21	    } else if (arg === 'build') {
22	      args.command = 'build';
23	    }
24	  }
25	
26	  return args;
27	}
