import fs from 'fs';
import path from 'path';
import Handlebars from 'handlebars';

export interface TemplateEngineOptions {
  templatesDir: string;
  layoutsDir: string;
  partialsDir: string;
}

export class TemplateEngine {
  private templatesDir: string;
  private layoutsDir: string;
  private partialsDir: string;
  private cache: Map<string, HandlebarsTemplateDelegate> = new Map();

  constructor(options: TemplateEngineOptions) {
    this.templatesDir = options.templatesDir;
    this.layoutsDir = options.layoutsDir;
    this.partialsDir = options.partialsDir;

    this.registerPartials();
  }

  private registerPartials(): void {
    if (!fs.existsSync(this.partialsDir)) {
      return;
    }

    const files = fs.readdirSync(this.partialsDir).filter(file => file.endsWith('.hbs'));

    for (const file of files) {
      const filePath = path.join(this.partialsDir, file);
      const content = fs.readFileSync(filePath, 'utf-8');
      const partialName = file.replace(/\.hbs$/, '');
      Handlebars.registerPartial(partialName, content);
    }
  }

  private getTemplate(filename: string): HandlebarsTemplateDelegate {
    if (this.cache.has(filename)) {
      return this.cache.get(filename)!;
    }

    const filePath = path.join(this.templatesDir, filename);
    if (!fs.existsSync(filePath)) {
      throw new Error(`Template not found: ${filename}`);
    }

    const content = fs.readFileSync(filePath, 'utf-8');
    const template = Handlebars.compile(content);
    this.cache.set(filename, template);
    return template;
  }

  private getLayout(layoutName: string): HandlebarsTemplateDelegate {
    return this.getTemplate(`layouts/${layoutName}`);
  }

  render(templateName: string, layoutName: string | undefined, data: any): string {
    const template = this.getTemplate(templateName);
    const renderedContent = template(data);

    if (!layoutName) {
      return renderedContent;
    }

    const layout = this.getLayout(layoutName);
    return layout({
      ...data,
      body: renderedContent
    });
  }

  renderWithLayout(content: string, layoutName: string | undefined, data: any): string {
    if (!layoutName) {
      return content;
    }

    const layout = this.getLayout(layoutName);
    return layout({
      ...data,
      body: content
    });
  }
}

